// Outlines the Stencil icon drawings (stencil/icons/icon-spec.ts) into filled shapes.
// Usage: pnpm stencil:icons           write the generated files
//        pnpm stencil:icons --check   exit 1 when a committed file is out of date
//   stencil/icons/icons.generated.ts            the set, at STROKE_WIDTH with flat caps
//   stencil/gallery/icon-variants.generated.ts  weight and cap variants, for comparing styles
//   ../site/stencil-icons.svg                   the few icons the website uses, as an SVG sprite
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import paper from 'paper'
import { PaperOffset } from 'paperjs-offset'

import { EDGE, GRID, ICON_SPEC, STROKE_WIDTH } from '../src/renderer/src/stencil/icons/icon-spec'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../src/renderer/src/stencil')
const WEIGHTS = [1.25, 1.33, 1.5, 1.75]

paper.setup(new paper.Size(GRID, GRID))

/** Rounds every number in path data to 2 decimals, which is well under a hundredth of a pixel. */
const round = (d: string): string => d.replace(/-?\d+\.\d+/g, (n) => String(+Number(n).toFixed(2)))

function outline(name: string, weight: number): { d: string; bounds: paper.Rectangle } {
  const spec = ICON_SPEC[name]
  const pieces: paper.PathItem[] = []
  for (const d of spec.strokes ?? []) {
    const path = new paper.Path({ pathData: d, insert: false })
    pieces.push(
      PaperOffset.offsetStroke(path, weight / 2, {
        cap: 'butt',
        join: 'round',
        insert: false
      }) as paper.PathItem
    )
  }
  if (spec.brand) {
    const mark = new paper.CompoundPath({ pathData: spec.brand, insert: false })
    mark.fitBounds(
      new paper.Rectangle(
        EDGE + 0.75,
        EDGE + 0.75,
        GRID - 2 * (EDGE + 0.75),
        GRID - 2 * (EDGE + 0.75)
      )
    )
    pieces.push(mark)
  }
  for (const [x, y, r] of spec.dots ?? []) {
    pieces.push(new paper.Path.Circle({ center: [x, y], radius: r, insert: false }))
  }
  const [first, ...rest] = pieces
  const shape = rest.reduce<paper.PathItem>(
    (all, piece) => all.unite(piece, { insert: false }),
    first
  )
  return { d: round(shape.pathData), bounds: shape.bounds }
}

const names = Object.keys(ICON_SPEC).sort()
const entries = (weight: number): string =>
  names.map((name) => `    '${name}': '${outline(name, weight).d}'`).join(',\n')

// The shipped set must stay inside the live area.
const outside = names.filter((name) => {
  const { x, y, width, height } = outline(name, STROKE_WIDTH).bounds
  const tolerance = 0.01
  return (
    x < EDGE - tolerance ||
    y < EDGE - tolerance ||
    x + width > GRID - EDGE + tolerance ||
    y + height > GRID - EDGE + tolerance
  )
})
if (outside.length > 0) {
  const detail = outside.map((name) => `${name} ${outline(name, STROKE_WIDTH).bounds.toString()}`)
  throw new Error(`These icons leave the live area:\n${detail.join('\n')}`)
}

const set = `// GENERATED by \`pnpm stencil:icons\` from stencil/icons/icon-spec.ts. Do not edit by hand.
// Each icon is one filled outline on a ${GRID}px grid, drawn from ${STROKE_WIDTH}px strokes.

export const ICON_NAMES = [
${names.map((n) => `  '${n}'`).join(',\n')}
] as const

export type IconName = (typeof ICON_NAMES)[number]

export const ICON_PATHS: Record<IconName, string> = {
${entries(STROKE_WIDTH).replace(/^ {2}/gm, '')}
}
`

const variants = `// GENERATED by \`pnpm stencil:icons\` from stencil/icons/icon-spec.ts. Do not edit by hand.
// The icons at each stroke weight (flat caps), for comparing styles in the gallery.
import type { IconName } from '../icons/icons.generated'

export const ICON_WEIGHTS = ${JSON.stringify(WEIGHTS)} as const

/** Keyed by weight, e.g. \`1.5\`. */
export const ICON_VARIANTS: Record<string, Record<IconName, string>> = {
${WEIGHTS.map((w) => `  '${w}': {\n${entries(w)}\n  }`).join(',\n')}
}
`

/** The icons the website uses. Add a name here to ship it in the sprite. */
const SITE_ICONS = ['arrow-right', 'connector', 'file', 'library', 'search']
const siteSprite = `<!-- GENERATED by \`pnpm stencil:icons\` from stencil/icons/icon-spec.ts. Do not edit by hand. -->
<svg xmlns="http://www.w3.org/2000/svg" style="display:none">
${SITE_ICONS.map((name) => `  <symbol id="${name}" viewBox="0 0 ${GRID} ${GRID}"><path d="${outline(name, STROKE_WIDTH).d}" /></symbol>`).join('\n')}
</svg>
`

const outputs = [
  {
    name: 'stencil/icons/icons.generated.ts',
    path: resolve(root, 'icons/icons.generated.ts'),
    next: set
  },
  {
    name: 'stencil/gallery/icon-variants.generated.ts',
    path: resolve(root, 'gallery/icon-variants.generated.ts'),
    next: variants
  },
  {
    name: 'site/stencil-icons.svg',
    path: resolve(root, '../../../../../site/stencil-icons.svg'),
    next: siteSprite
  }
]

if (process.argv.includes('--check')) {
  for (const output of outputs) {
    if (readFileSync(output.path, 'utf8') !== output.next) {
      console.error(`${output.name} is out of date. Run \`pnpm stencil:icons\`.`)
      process.exitCode = 1
    } else {
      console.log(`${output.name} is up to date.`)
    }
  }
} else {
  for (const output of outputs) {
    writeFileSync(output.path, output.next)
    console.log(`Wrote ${output.path.replace(process.cwd() + '/', '')}`)
  }
}
